messageValues.content:
=Analiza este balance de auditoría y detecta SOLO los problemas más importantes. Responde SOLO JSON:
{
  "alert_level": "🚨 CRÍTICO" / "🟡 ADVERTENCIA" / "ℹ️ INFO",
  "title": "Título breve del problema",
  "description": "Descripción de 1-2 líneas",
  "action": "Acción recomendada",
  "nia_applicable": "NIA xxx"
}

Balance:
{{ JSON.stringify($node["Loop - Each Audit"].json.current_item) }}

parameters.blocks:
=[
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": "*{{ JSON.parse($node["Claude - Analyze for Alerts"].json.body).alert_level }} {{ JSON.parse($node["Claude - Analyze for Alerts"].json.body).title }}*\n{{ JSON.parse($node["Claude - Analyze for Alerts"].json.body).description }}"
    }
  },
  {
    "type": "section",
    "fields": [
      {
        "type": "mrkdwn",
        "text": "*Cliente:*\n{{ $node["Loop - Each Audit"].json.current_item.cliente_nombre }}"
      },
      {
        "type": "mrkdwn",
        "text": "*NIA Aplicable:*\n{{ JSON.parse($node["Claude - Analyze for Alerts"].json.body).nia_applicable }}"
      }
    ]
  },
  {
    "type": "section",
    "text": {
      "type": "mrkdwn",
      "text": "*Acción Recomendada:*\n{{ JSON.parse($node["Claude - Analyze for Alerts"].json.body).action }}"
    }
  },
  {
    "type": "actions",
    "elements": [
      {
        "type": "button",
        "text": {
          "type": "plain_text",
          "text": "Ver en SocioAI"
        },
        "url": "http://localhost:3000/auditorias/{{ $node["Loop - Each Audit"].json.current_item.audit_id }}"
      }
    ]
  }
]
